import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Module: vm_primitives","description":"","frontmatter":{},"headers":[],"relativePath":"api/host/handl_runtime/vm_primitives.md","filePath":"api/host/handl_runtime/vm_primitives.md"}`),a={name:`api/host/handl_runtime/vm_primitives.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><strong>handl_runtime &gt; vm_primitives</strong></p><h1 id="module-vm-primitives" tabindex="-1">Module: vm_primitives <a class="header-anchor" href="#module-vm-primitives" aria-label="Permalink to “Module: vm_primitives”">​</a></h1><h2 id="contents" tabindex="-1">Contents <a class="header-anchor" href="#contents" aria-label="Permalink to “Contents”">​</a></h2><p><strong>Structs</strong></p><ul><li><a href="#arraydroplastfn"><code>ArrayDropLastFn</code></a> - <code>array_drop_last(xs)</code> — return <code>xs</code> without its last element.</li><li><a href="#bindfn"><code>BindFn</code></a> - <code>bind(name, value)</code> — bind <code>name</code> → <code>value</code> in the current (top) scope.</li><li><a href="#callfn"><code>CallFn</code></a> - <code>call(callee, args)</code> — apply <code>callee</code> to <code>args</code>.</li><li><a href="#ctxfn"><code>CtxFn</code></a> - <code>ctx()</code> — return the current VM context as a JSON object.</li><li><a href="#evalfn"><code>EvalFn</code></a> - <code>eval(node)</code> — evaluate a node by dispatching on its <code>kind</code> field.</li><li><a href="#evalschemearrfn"><code>EvalSchemeArrFn</code></a> - <code>eval_scheme_Arr(node)</code> — extract the <code>value</code> field from an Arr node.</li><li><a href="#evalschemeconstfn"><code>EvalSchemeConstFn</code></a> - <code>eval_scheme_Const(node)</code> — extract the <code>value</code> field from a Const node.</li><li><a href="#ffifn"><code>FfiFn</code></a> - <code>ffi(module, name, args)</code> — foreign function interface (minimal).</li><li><a href="#findophandlerfn"><code>FindOpHandlerFn</code></a> - <code>find_op_handler(stack, name)</code> — search the handler stack for an op.</li><li><a href="#instanceoffn"><code>InstanceOfFn</code></a> - <code>instance_of(value, nominal)</code> — instanceof over the nominal links</li><li><a href="#lookupevalschemefn"><code>LookupEvalSchemeFn</code></a> - <code>lookup_eval_scheme(kind)</code> — return the eval scheme name for a node kind.</li><li><a href="#lookupfn"><code>LookupFn</code></a> - <code>lookup(name)</code> — look up <code>name</code> in the scope stack (innermost-first).</li><li><a href="#makeclosurefn"><code>MakeClosureFn</code></a> - <code>make_closure(params, body, env)</code> — create a closure record.</li><li><a href="#popscopefn"><code>PopScopeFn</code></a> - <code>pop_scope()</code> — pop the top scope from the scope stack.</li><li><a href="#pushscopefn"><code>PushScopeFn</code></a> - <code>push_scope()</code> — push a fresh scope onto the scope stack.</li><li><a href="#setfieldfn"><code>SetFieldFn</code></a> - <code>setfield(obj, key, value)</code> — set a field on the VM context.</li><li><a href="#symfn"><code>SymFn</code></a> - <code>sym()</code> / <code>sym(parent)</code> / <code>sym(&quot;seed&quot;)</code> / <code>sym(&quot;seed&quot;, parent[, ty])</code></li><li><a href="#symmodule"><code>SymModule</code></a> - A <code>Send + Sync</code> wrapper exposing the Phase 2 nominal primitives as the</li><li><a href="#vmpatternmatchfn"><code>VmPatternMatchFn</code></a> - <code>vm_pattern_match(pattern, value)</code> — match <code>value</code> against <code>pattern</code>.</li><li><a href="#vmprimitivesmodule"><code>VmPrimitivesModule</code></a> - A host-function module providing the VM primitives that <code>exec_model.hnl</code></li><li><a href="#vmstate"><code>VmState</code></a> - The mutable state of the VM primitives module: a scope stack and a context</li></ul><p><strong>Constants</strong></p><ul><li><a href="#sym-module-name"><code>SYM_MODULE_NAME</code></a> - Name of the module: <code>sym(x)</code> / <code>sym.instanceof(v, n)</code> in surface code.</li></ul><hr><h2 id="handl-runtime-vm-primitives-arraydroplastfn" tabindex="-1">handl_runtime::vm_primitives::ArrayDropLastFn <a class="header-anchor" href="#handl-runtime-vm-primitives-arraydroplastfn" aria-label="Permalink to “handl_runtime::vm_primitives::ArrayDropLastFn”">​</a></h2><p><em>Struct</em></p><p><code>array_drop_last(xs)</code> — return <code>xs</code> without its last element.</p><p>This host function exists because <code>exec_model.hnl</code> defines <code>array_drop_last</code> after <code>pop_handler</code> in the <code>do { ... }</code> block, so <code>pop_handler</code>&#39;s captured env doesn&#39;t include it.</p><p>Returns <code>array.slice(xs, 0, len-1)</code>. For an empty array, returns <code>[]</code>.</p><p><strong>Unit Struct</strong></p><p><strong>Trait Implementations:</strong></p><ul><li><strong>Function</strong><ul><li><code>fn call(self: &amp;Self, args: &amp;[Value], _ctx: &amp; mut EvalContext) -&gt; Result&lt;Value, EvalError&gt;</code></li></ul></li></ul><h2 id="handl-runtime-vm-primitives-bindfn" tabindex="-1">handl_runtime::vm_primitives::BindFn <a class="header-anchor" href="#handl-runtime-vm-primitives-bindfn" aria-label="Permalink to “handl_runtime::vm_primitives::BindFn”">​</a></h2><p><em>Struct</em></p><p><code>bind(name, value)</code> — bind <code>name</code> → <code>value</code> in the current (top) scope.</p><p><strong>Fields:</strong></p><ul><li><code>state: std::sync::Arc&lt;std::sync::Mutex&lt;VmState&gt;&gt;</code></li></ul><p><strong>Trait Implementations:</strong></p><ul><li><strong>Function</strong><ul><li><code>fn call(self: &amp;Self, args: &amp;[Value], _ctx: &amp; mut EvalContext) -&gt; Result&lt;Value, EvalError&gt;</code></li></ul></li></ul><h2 id="handl-runtime-vm-primitives-callfn" tabindex="-1">handl_runtime::vm_primitives::CallFn <a class="header-anchor" href="#handl-runtime-vm-primitives-callfn" aria-label="Permalink to “handl_runtime::vm_primitives::CallFn”">​</a></h2><p><em>Struct</em></p><p><code>call(callee, args)</code> — apply <code>callee</code> to <code>args</code>.</p><ul><li>Arrow-values (<code>{&quot;__arrow__&quot;: true, ...}</code>) are dispatched via <code>ctx.try_call_value</code>.</li><li>Closure records (<code>{&quot;__closure__&quot;: true, ...}</code>) return the <code>body</code> field (minimal — cannot evaluate the body from a host function).</li><li>Other callees return <code>Null</code>.</li></ul><p><strong>Unit Struct</strong></p><p><strong>Trait Implementations:</strong></p><ul><li><strong>Function</strong><ul><li><code>fn call(self: &amp;Self, args: &amp;[Value], ctx: &amp; mut EvalContext) -&gt; Result&lt;Value, EvalError&gt;</code></li></ul></li></ul><h2 id="handl-runtime-vm-primitives-ctxfn" tabindex="-1">handl_runtime::vm_primitives::CtxFn <a class="header-anchor" href="#handl-runtime-vm-primitives-ctxfn" aria-label="Permalink to “handl_runtime::vm_primitives::CtxFn”">​</a></h2><p><em>Struct</em></p><p><code>ctx()</code> — return the current VM context as a JSON object.</p><p><strong>Fields:</strong></p><ul><li><code>state: std::sync::Arc&lt;std::sync::Mutex&lt;VmState&gt;&gt;</code></li></ul><p><strong>Trait Implementations:</strong></p><ul><li><strong>Function</strong><ul><li><code>fn call(self: &amp;Self, _args: &amp;[Value], _ctx: &amp; mut EvalContext) -&gt; Result&lt;Value, EvalError&gt;</code></li></ul></li></ul><h2 id="handl-runtime-vm-primitives-evalfn" tabindex="-1">handl_runtime::vm_primitives::EvalFn <a class="header-anchor" href="#handl-runtime-vm-primitives-evalfn" aria-label="Permalink to “handl_runtime::vm_primitives::EvalFn”">​</a></h2><p><em>Struct</em></p><p><code>eval(node)</code> — evaluate a node by dispatching on its <code>kind</code> field.</p><p>This host function exists because <code>exec_model.hnl</code> defines <code>eval</code> near the end of its <code>do { ... }</code> block (after <code>eval_block</code>, <code>proj_child</code>, etc.). The block uses sequential binding, so functions defined earlier cannot capture <code>eval</code> in their closure environment. When those earlier functions call <code>eval(...)</code>, the tree-walk engine falls back to <code>call_host_fn(&quot;eval&quot;, ...)</code>, which dispatches here.</p><p>Minimal: handles <code>Arr</code> and <code>Const</code> kinds (returns <code>node.value</code>). Other kinds return <code>Null</code>.</p><p><strong>Unit Struct</strong></p><p><strong>Trait Implementations:</strong></p><ul><li><strong>Function</strong><ul><li><code>fn call(self: &amp;Self, args: &amp;[Value], _ctx: &amp; mut EvalContext) -&gt; Result&lt;Value, EvalError&gt;</code></li></ul></li></ul><h2 id="handl-runtime-vm-primitives-evalschemearrfn" tabindex="-1">handl_runtime::vm_primitives::EvalSchemeArrFn <a class="header-anchor" href="#handl-runtime-vm-primitives-evalschemearrfn" aria-label="Permalink to “handl_runtime::vm_primitives::EvalSchemeArrFn”">​</a></h2><p><em>Struct</em></p><p><code>eval_scheme_Arr(node)</code> — extract the <code>value</code> field from an Arr node.</p><p><strong>Unit Struct</strong></p><p><strong>Trait Implementations:</strong></p><ul><li><strong>Function</strong><ul><li><code>fn call(self: &amp;Self, args: &amp;[Value], _ctx: &amp; mut EvalContext) -&gt; Result&lt;Value, EvalError&gt;</code></li></ul></li></ul><h2 id="handl-runtime-vm-primitives-evalschemeconstfn" tabindex="-1">handl_runtime::vm_primitives::EvalSchemeConstFn <a class="header-anchor" href="#handl-runtime-vm-primitives-evalschemeconstfn" aria-label="Permalink to “handl_runtime::vm_primitives::EvalSchemeConstFn”">​</a></h2><p><em>Struct</em></p><p><code>eval_scheme_Const(node)</code> — extract the <code>value</code> field from a Const node.</p><p><strong>Unit Struct</strong></p><p><strong>Trait Implementations:</strong></p><ul><li><strong>Function</strong><ul><li><code>fn call(self: &amp;Self, args: &amp;[Value], _ctx: &amp; mut EvalContext) -&gt; Result&lt;Value, EvalError&gt;</code></li></ul></li></ul><h2 id="handl-runtime-vm-primitives-ffifn" tabindex="-1">handl_runtime::vm_primitives::FfiFn <a class="header-anchor" href="#handl-runtime-vm-primitives-ffifn" aria-label="Permalink to “handl_runtime::vm_primitives::FfiFn”">​</a></h2><p><em>Struct</em></p><p><code>ffi(module, name, args)</code> — foreign function interface (minimal).</p><p>Handles <code>ffi(&quot;native&quot;, &quot;add&quot;, [a, b])</code> and a few other arithmetic ops. Other dispatches return <code>Null</code>.</p><p><strong>Unit Struct</strong></p><p><strong>Trait Implementations:</strong></p><ul><li><strong>Function</strong><ul><li><code>fn call(self: &amp;Self, args: &amp;[Value], _ctx: &amp; mut EvalContext) -&gt; Result&lt;Value, EvalError&gt;</code></li></ul></li></ul><h2 id="handl-runtime-vm-primitives-findophandlerfn" tabindex="-1">handl_runtime::vm_primitives::FindOpHandlerFn <a class="header-anchor" href="#handl-runtime-vm-primitives-findophandlerfn" aria-label="Permalink to “handl_runtime::vm_primitives::FindOpHandlerFn”">​</a></h2><p><em>Struct</em></p><p><code>find_op_handler(stack, name)</code> — search the handler stack for an op.</p><p>This host function exists because <code>exec_model.hnl</code> defines <code>find_op_handler</code> after <code>call_op</code> in the <code>do { ... }</code> block, so <code>call_op</code>&#39;s captured env doesn&#39;t include it.</p><p>Walks <code>stack</code> (an array) from first to last. For each handler, checks if its <code>impls</code> field (an object) has the key <code>name</code>. Returns the first matching implementation value, or <code>Null</code> if none found.</p><p><strong>Unit Struct</strong></p><p><strong>Trait Implementations:</strong></p><ul><li><strong>Function</strong><ul><li><code>fn call(self: &amp;Self, args: &amp;[Value], _ctx: &amp; mut EvalContext) -&gt; Result&lt;Value, EvalError&gt;</code></li></ul></li></ul><h2 id="handl-runtime-vm-primitives-instanceoffn" tabindex="-1">handl_runtime::vm_primitives::InstanceOfFn <a class="header-anchor" href="#handl-runtime-vm-primitives-instanceoffn" aria-label="Permalink to “handl_runtime::vm_primitives::InstanceOfFn”">​</a></h2><p><em>Struct</em></p><p><code>instance_of(value, nominal)</code> — instanceof over the nominal links (ADR-0106 §2, reread per ADR-0154 §2).</p><p>The kernel (<code>handl_value::instance_of</code>) owns the semantics: <code>x : T</code> resolves <code>x</code>&#39;s <code>type</code>-link head, then the <code>&lt;:</code> walk is <code>head.has_ancestor(nominal)</code> over <code>parent</code> links.</p><ul><li><code>value</code> a nominal reads both its own <code>parent</code> chain (the <code>&lt;:</code> read — <code>Float instanceof Number</code>) and its <code>ty</code> link (the membership read — <code>Int instanceof Type</code>).</li><li><code>value</code> an object reads its <code>&quot;type&quot;</code> field (ctor values); anything else — including a <code>__tag__</code> datum — is a plain <code>type.Obj</code> member. (The <code>__tag__</code> nominal bridge was deleted, ADR-0152 §Migration.)</li><li><code>value</code> a scalar resolves through the literal defaults (<code>1 instanceof Nat</code>, <code>1.5 instanceof Float</code>, ADR-0154 §5).</li><li><code>nominal</code> resolves through <code>nominal_head</code> — a sym, a <code>{&quot;__former__&quot;: s}</code> family object, or a <code>{&quot;__type__&quot;: i}</code> universe encoding (→ <code>type.Type</code>); anything else is a <code>TypeMismatch</code>.</li><li>A value with no resolvable head is simply not an instance: <code>Bool(false)</code>, no error.</li></ul><p><strong>Unit Struct</strong></p><p><strong>Trait Implementations:</strong></p><ul><li><strong>Function</strong><ul><li><code>fn call(self: &amp;Self, args: &amp;[Value], _ctx: &amp; mut EvalContext) -&gt; Result&lt;Value, EvalError&gt;</code></li></ul></li></ul><h2 id="handl-runtime-vm-primitives-lookupevalschemefn" tabindex="-1">handl_runtime::vm_primitives::LookupEvalSchemeFn <a class="header-anchor" href="#handl-runtime-vm-primitives-lookupevalschemefn" aria-label="Permalink to “handl_runtime::vm_primitives::LookupEvalSchemeFn”">​</a></h2><p><em>Struct</em></p><p><code>lookup_eval_scheme(kind)</code> — return the eval scheme name for a node kind.</p><p>Returns <code>&quot;eval_scheme_&lt;kind&gt;&quot;</code> for known kinds (<code>Arr</code>, <code>Const</code>), or <code>Null</code> for unknown kinds.</p><p><strong>Unit Struct</strong></p><p><strong>Trait Implementations:</strong></p><ul><li><strong>Function</strong><ul><li><code>fn call(self: &amp;Self, args: &amp;[Value], _ctx: &amp; mut EvalContext) -&gt; Result&lt;Value, EvalError&gt;</code></li></ul></li></ul><h2 id="handl-runtime-vm-primitives-lookupfn" tabindex="-1">handl_runtime::vm_primitives::LookupFn <a class="header-anchor" href="#handl-runtime-vm-primitives-lookupfn" aria-label="Permalink to “handl_runtime::vm_primitives::LookupFn”">​</a></h2><p><em>Struct</em></p><p><code>lookup(name)</code> — look up <code>name</code> in the scope stack (innermost-first). Returns the bound value or <code>Null</code> if unbound.</p><p><strong>Fields:</strong></p><ul><li><code>state: std::sync::Arc&lt;std::sync::Mutex&lt;VmState&gt;&gt;</code></li></ul><p><strong>Trait Implementations:</strong></p><ul><li><strong>Function</strong><ul><li><code>fn call(self: &amp;Self, args: &amp;[Value], _ctx: &amp; mut EvalContext) -&gt; Result&lt;Value, EvalError&gt;</code></li></ul></li></ul><h2 id="handl-runtime-vm-primitives-makeclosurefn" tabindex="-1">handl_runtime::vm_primitives::MakeClosureFn <a class="header-anchor" href="#handl-runtime-vm-primitives-makeclosurefn" aria-label="Permalink to “handl_runtime::vm_primitives::MakeClosureFn”">​</a></h2><p><em>Struct</em></p><p><code>make_closure(params, body, env)</code> — create a closure record.</p><p><strong>Unit Struct</strong></p><p><strong>Trait Implementations:</strong></p><ul><li><strong>Function</strong><ul><li><code>fn call(self: &amp;Self, args: &amp;[Value], _ctx: &amp; mut EvalContext) -&gt; Result&lt;Value, EvalError&gt;</code></li></ul></li></ul><h2 id="handl-runtime-vm-primitives-popscopefn" tabindex="-1">handl_runtime::vm_primitives::PopScopeFn <a class="header-anchor" href="#handl-runtime-vm-primitives-popscopefn" aria-label="Permalink to “handl_runtime::vm_primitives::PopScopeFn”">​</a></h2><p><em>Struct</em></p><p><code>pop_scope()</code> — pop the top scope from the scope stack.</p><p><strong>Fields:</strong></p><ul><li><code>state: std::sync::Arc&lt;std::sync::Mutex&lt;VmState&gt;&gt;</code></li></ul><p><strong>Trait Implementations:</strong></p><ul><li><strong>Function</strong><ul><li><code>fn call(self: &amp;Self, _args: &amp;[Value], _ctx: &amp; mut EvalContext) -&gt; Result&lt;Value, EvalError&gt;</code></li></ul></li></ul><h2 id="handl-runtime-vm-primitives-pushscopefn" tabindex="-1">handl_runtime::vm_primitives::PushScopeFn <a class="header-anchor" href="#handl-runtime-vm-primitives-pushscopefn" aria-label="Permalink to “handl_runtime::vm_primitives::PushScopeFn”">​</a></h2><p><em>Struct</em></p><p><code>push_scope()</code> — push a fresh scope onto the scope stack.</p><p><strong>Fields:</strong></p><ul><li><code>state: std::sync::Arc&lt;std::sync::Mutex&lt;VmState&gt;&gt;</code></li></ul><p><strong>Trait Implementations:</strong></p><ul><li><strong>Function</strong><ul><li><code>fn call(self: &amp;Self, _args: &amp;[Value], _ctx: &amp; mut EvalContext) -&gt; Result&lt;Value, EvalError&gt;</code></li></ul></li></ul><h2 id="handl-runtime-vm-primitives-sym-module-name" tabindex="-1">handl_runtime::vm_primitives::SYM_MODULE_NAME <a class="header-anchor" href="#handl-runtime-vm-primitives-sym-module-name" aria-label="Permalink to “handl_runtime::vm_primitives::SYM_MODULE_NAME”">​</a></h2><p><em>Constant</em>: <code>&amp;str</code></p><p>Name of the module: <code>sym(x)</code> / <code>sym.instanceof(v, n)</code> in surface code.</p><h2 id="handl-runtime-vm-primitives-setfieldfn" tabindex="-1">handl_runtime::vm_primitives::SetFieldFn <a class="header-anchor" href="#handl-runtime-vm-primitives-setfieldfn" aria-label="Permalink to “handl_runtime::vm_primitives::SetFieldFn”">​</a></h2><p><em>Struct</em></p><p><code>setfield(obj, key, value)</code> — set a field on the VM context.</p><p>Updates the internal context&#39;s <code>key</code> field to <code>value</code> and returns <code>value</code>. The first argument (the context object) is used for identification but the actual update is to the internal mutable state.</p><p><strong>Fields:</strong></p><ul><li><code>state: std::sync::Arc&lt;std::sync::Mutex&lt;VmState&gt;&gt;</code></li></ul><p><strong>Trait Implementations:</strong></p><ul><li><strong>Function</strong><ul><li><code>fn call(self: &amp;Self, args: &amp;[Value], _ctx: &amp; mut EvalContext) -&gt; Result&lt;Value, EvalError&gt;</code></li></ul></li></ul><h2 id="handl-runtime-vm-primitives-symfn" tabindex="-1">handl_runtime::vm_primitives::SymFn <a class="header-anchor" href="#handl-runtime-vm-primitives-symfn" aria-label="Permalink to “handl_runtime::vm_primitives::SymFn”">​</a></h2><p><em>Struct</em></p><p><code>sym()</code> / <code>sym(parent)</code> / <code>sym(&quot;seed&quot;)</code> / <code>sym(&quot;seed&quot;, parent[, ty])</code> — nominal identity mints (ADR-0106 §2, ADR-0154 §1/§2).</p><ul><li><code>sym()</code> — fresh nominal identity with no parent (a root sym).</li><li><code>sym(A)</code> — fresh nominal identity whose nominal parent is <code>A</code>; <code>A</code> must itself be a nominal object (<code>{&quot;__sym__&quot;: ...}</code>), otherwise a <code>TypeMismatch</code> error is returned.</li><li><code>sym(&quot;seed&quot;)</code> — the <em>deterministic</em> mint of ADR-0154 §1: the nominal for a declared name, idempotent and stable across processes (the handle is a content hash of the seed, not the fresh counter). <code>sym(&quot;type.Int&quot;)</code> twice is the <em>same</em> nominal; plain <code>sym()</code> stays fresh for locals.</li><li><code>sym(&quot;seed&quot;, parent)</code> / <code>sym(&quot;seed&quot;, parent, ty)</code> — the declared nominal with its links: <code>parent</code> is the <code>&lt;:</code> edge, <code>ty</code> the <code>type</code>/membership edge (<code>Int.ty = Type</code>; <code>null</code> = absent).</li></ul><p>The returned value is the explicit JSON encoding <code>{&quot;__sym__&quot;: {&quot;handle&quot;: &amp;lt;n&gt;, &quot;name&quot;: &quot;...&quot;, &quot;parent&quot;: &amp;lt;sym or null&gt;, &quot;type&quot;: &amp;lt;sym or null&gt;}}</code>. Identity is the <code>handle</code>: two distinct <code>sym()</code> calls are never equal; two <code>sym(&quot;seed&quot;)</code> mints are always equal.</p><p>The implementation delegates to <code>handl-value</code>, the single owner of the nominal value model and its serialization (ADR-0106 &quot;Implementation notes&quot;: <code>crates/handl-value</code> — the value model; objects gain a nominal identity field while remaining serializable tagged data).</p><p><strong>Unit Struct</strong></p><p><strong>Trait Implementations:</strong></p><ul><li><strong>Function</strong><ul><li><code>fn call(self: &amp;Self, args: &amp;[Value], _ctx: &amp; mut EvalContext) -&gt; Result&lt;Value, EvalError&gt;</code></li></ul></li></ul><h2 id="handl-runtime-vm-primitives-symmodule" tabindex="-1">handl_runtime::vm_primitives::SymModule <a class="header-anchor" href="#handl-runtime-vm-primitives-symmodule" aria-label="Permalink to “handl_runtime::vm_primitives::SymModule”">​</a></h2><p><em>Struct</em></p><p>A <code>Send + Sync</code> wrapper exposing the Phase 2 nominal primitives as the <code>sym</code> module: <code>sym</code> (0- or 1-arg mint) and <code>instanceof</code> (alias of <code>instance_of</code>). Delegates to a [<code>VmPrimitivesModule</code>] instance held by value (its function structs are <code>Send + Sync</code>; shared scope state is behind <code>Arc&lt;Mutex&lt;..&gt;&gt;</code>).</p><p><strong>Fields:</strong></p><ul><li><code>inner: VmPrimitivesModule</code></li></ul><p><strong>Methods:</strong></p><ul><li><code>fn new() -&gt; Self</code> - Create a fresh <code>sym</code> module (own VM primitive state).</li></ul><p><strong>Trait Implementations:</strong></p><ul><li><strong>Module</strong><ul><li><code>fn name(self: &amp;Self) -&gt; &amp;str</code></li><li><code>fn function(self: &amp;Self, name: &amp;str) -&gt; Option&lt;&amp;dyn Function&gt;</code></li><li><code>fn functions(self: &amp;Self) -&gt; Vec&lt;(&amp;str, &amp;dyn Function)&gt;</code></li></ul></li><li><strong>Default</strong><ul><li><code>fn default() -&gt; Self</code></li></ul></li></ul><h2 id="handl-runtime-vm-primitives-vmpatternmatchfn" tabindex="-1">handl_runtime::vm_primitives::VmPatternMatchFn <a class="header-anchor" href="#handl-runtime-vm-primitives-vmpatternmatchfn" aria-label="Permalink to “handl_runtime::vm_primitives::VmPatternMatchFn”">​</a></h2><p><em>Struct</em></p><p><code>vm_pattern_match(pattern, value)</code> — match <code>value</code> against <code>pattern</code>.</p><ul><li>Wildcard <code>&quot;_&quot;</code> → <code>{}</code> (match success, no bindings).</li><li>Variable (any other string) → <code>{pattern: value}</code> (bind the variable).</li><li>Literal equality → <code>{}</code> (match success).</li><li>Otherwise → <code>Null</code> (no match).</li></ul><p><strong>Unit Struct</strong></p><p><strong>Trait Implementations:</strong></p><ul><li><strong>Function</strong><ul><li><code>fn call(self: &amp;Self, args: &amp;[Value], _ctx: &amp; mut EvalContext) -&gt; Result&lt;Value, EvalError&gt;</code></li></ul></li></ul><h2 id="handl-runtime-vm-primitives-vmprimitivesmodule" tabindex="-1">handl_runtime::vm_primitives::VmPrimitivesModule <a class="header-anchor" href="#handl-runtime-vm-primitives-vmprimitivesmodule" aria-label="Permalink to “handl_runtime::vm_primitives::VmPrimitivesModule”">​</a></h2><p><em>Struct</em></p><p>A host-function module providing the VM primitives that <code>exec_model.hnl</code> calls. Register it as a dependency of the exec model <code>HandlModule</code>:</p><div class="language-ignore"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ignore</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>HandlModule::new(&quot;exec_model&quot;, source, funcs)</span></span>
<span class="line"><span>    .with_dependency(VmPrimitivesModule::new())</span></span></code></pre></div><p>Each call to [<code>VmPrimitivesModule::new</code>] creates a fresh module with its own scope stack and context — state is not shared across instances.</p><p><strong>Fields:</strong></p><ul><li><code>push_scope_fn: PushScopeFn</code></li><li><code>pop_scope_fn: PopScopeFn</code></li><li><code>bind_fn: BindFn</code></li><li><code>lookup_fn: LookupFn</code></li><li><code>make_closure_fn: MakeClosureFn</code></li><li><code>call_fn: CallFn</code></li><li><code>vm_pattern_match_fn: VmPatternMatchFn</code></li><li><code>lookup_eval_scheme_fn: LookupEvalSchemeFn</code></li><li><code>eval_scheme_arr_fn: EvalSchemeArrFn</code></li><li><code>eval_scheme_const_fn: EvalSchemeConstFn</code></li><li><code>ffi_fn: FfiFn</code></li><li><code>setfield_fn: SetFieldFn</code></li><li><code>ctx_fn: CtxFn</code></li><li><code>eval_fn: EvalFn</code></li><li><code>find_op_handler_fn: FindOpHandlerFn</code></li><li><code>array_drop_last_fn: ArrayDropLastFn</code></li><li><code>sym_fn: SymFn</code></li><li><code>instance_of_fn: InstanceOfFn</code></li></ul><p><strong>Methods:</strong></p><ul><li><code>fn new() -&gt; Self</code> - Create a fresh <code>VmPrimitivesModule</code> with an empty scope stack and a</li></ul><p><strong>Trait Implementations:</strong></p><ul><li><strong>Module</strong><ul><li><code>fn name(self: &amp;Self) -&gt; &amp;str</code></li><li><code>fn function(self: &amp;Self, name: &amp;str) -&gt; Option&lt;&amp;dyn Function&gt;</code></li><li><code>fn functions(self: &amp;Self) -&gt; Vec&lt;(&amp;str, &amp;dyn Function)&gt;</code></li></ul></li><li><strong>Default</strong><ul><li><code>fn default() -&gt; Self</code></li></ul></li></ul><h2 id="handl-runtime-vm-primitives-vmstate" tabindex="-1">handl_runtime::vm_primitives::VmState <a class="header-anchor" href="#handl-runtime-vm-primitives-vmstate" aria-label="Permalink to “handl_runtime::vm_primitives::VmState”">​</a></h2><p><em>Struct</em></p><p>The mutable state of the VM primitives module: a scope stack and a context record.</p><p><strong>Fields:</strong></p><ul><li><code>scopes: Vec&lt;std::collections::HashMap&lt;String, serde_json::Value&gt;&gt;</code> - The scope stack — a stack of name→value maps. <code>push_scope</code> pushes a</li><li><code>context: serde_json::Value</code> - The VM context record, exposed via the <code>ctx()</code> host function and</li></ul><p><strong>Methods:</strong></p><ul><li><code>fn new() -&gt; Self</code></li></ul>`,168)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};